type Room = { id: string; name: string; capacity: number; tags: string[]; unavailableSlotIds: string[] }
type Demand = { id: string; subject: string; groupIds: string[]; teacherIds: string[]; roomIds: string[]; weeklyCount: number; requiredTags: string[]; allowedSlotIds: string[]; maxPerDay: number; syncKey: string; sourceLessonIds: string[]; activeFrom?:string|null; activeUntil?:string|null; weekTypes?:string[] }
type Assignment = { eventId: string; slotId: string; roomId: string }
type EventChain = { id: string; eventIds: string[]; sameDay: boolean; maxGapMinutes: number | null }
type PlanningInput = { periodStart: string; weekType?:string; confirmed: boolean; slots: Slot[]; groups: Group[]; teachers: Teacher[]; rooms: Room[]; demands: Demand[]; baseline: Assignment[]; pins: Assignment[]; eventChains: EventChain[]; preferences: { earlyWeight: number; changeWeight: number; roomChangeWeight: number }; notes: string }
