type AgentTask = { id: string; status: string; message: string; revision: number; proposal?: { kind?: string; runId?: string; expectedRevision?: number; configRevision?: number }; issues?: unknown[] }
type Question = { id: string; code: string; message: string; entityIds: string[]; targets?: { type: string; id: string; label: string }[]; status: string; answer: string | null; deadline?: string; overdue?: boolean; channel?: string; delivery?: string; notice?: string }
