const days = ['Понедельник', 'Вторник', 'Среда', 'Четверг', 'Пятница', 'Суббота']
const shortDays = ['Пн', 'Вт', 'Ср', 'Чт', 'Пт', 'Сб']
const activeStatuses = new Set(['queued', 'running'])
const successfulStatuses = new Set(['optimal', 'feasible'])
const labels: Record<string, string> = { queued: 'В очереди', running: 'Расчёт выполняется', optimal: 'Найден оптимальный вариант', feasible: 'Найден допустимый вариант', infeasible: 'Допустимого варианта нет', unknown: 'Расчёт не завершён', invalid: 'Проверка не пройдена', failed: 'Ошибка расчёта', interrupted: 'Расчёт прерван', cancelled: 'Расчёт отменён', approved: 'Сохранено в черновике', rejected: 'Предложение отклонено', stale: 'Исходная версия изменилась', awaiting_approval: 'Ждёт вашего решения', completed: 'Выполнено', needs_configuration: 'Нужна настройка' }
const dataTabs: { id: DataTab; title: string }[] = [{ id: 'week', title: 'Неделя' }, { id: 'groups', title: 'Группы' }, { id: 'teachers', title: 'Учителя' }, { id: 'rooms', title: 'Кабинеты' }, { id: 'demands', title: 'Нагрузка' }, { id: 'pins', title: 'Закрепления' }]
const entityTitles: Record<EntityKey, string> = { groups: 'Группа', teachers: 'Преподаватель', rooms: 'Кабинет', demands: 'Учебная нагрузка' }
const canonical = (value: string) => value.normalize('NFKC').trim().replace(/\s+/gu, ' ').toLocaleLowerCase('ru')
const split = (value: string) => { const found = new Set<string>(); return value.split(/[,\r\n]+/u).map(item => item.trim()).filter(item => { const key = canonical(item); if (!item || found.has(key)) return false; found.add(key); return true }) }
const numeric = (value: string) => value === '' ? NaN : Number(value)
const numberValue = (value: number) => Number.isFinite(value) ? value : ''
const newId = (prefix: string) => `${prefix}_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 7)}`
function monday() { const date = new Intl.DateTimeFormat('sv-SE', { timeZone: 'Europe/Moscow', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date()); const value = new Date(`${date}T12:00:00Z`); value.setUTCDate(value.getUTCDate() - (value.getUTCDay() + 6) % 7); return value.toISOString().slice(0, 10) }
function blankInput(periodStart = monday()): PlanningInput { return { periodStart, confirmed: false, slots: [], groups: [], teachers: [], rooms: [], demands: [], baseline: [], pins: [], eventChains: [], preferences: { earlyWeight: 1, changeWeight: 100, roomChangeWeight: 10 }, notes: '' } }
function listOf<T>(value: unknown, key: string): T[] { if (Array.isArray(value)) return value as T[]; if (value && typeof value === 'object' && key in value && Array.isArray((value as Record<string, unknown>)[key])) return (value as Record<string, unknown>)[key] as T[]; return [] }
function parseInput(value: unknown): PlanningInput {
 const fail = (label: string): never => { throw new Error(`Проверьте JSON: ${label}. Условия не применены.`) }
 const object = (item: unknown, label: string, keys: string[]) => { if (!item || typeof item !== 'object' || Array.isArray(item)) return fail(`${label} должен быть объектом`); const result = item as Record<string, unknown>; if (Object.keys(result).some(key => !keys.includes(key))) return fail(`${label} содержит неизвестное поле`); return result }
 const array = (item: unknown, label: string, max: number, optional = false): unknown[] => { if (item === undefined && optional) return []; if (!Array.isArray(item) || item.length > max) return fail(`${label}: ожидается список до ${max} записей`); return item }
 const string = (item: unknown, label: string, max: number, fallback?: string) => { if (item === undefined && fallback !== undefined) return fallback; if (typeof item !== 'string' || item.length > max || /[\u0000-\u001f\u007f-\u009f\ud800-\udfff]/u.test(item)) return fail(`${label}: ожидается текст до ${max} символов без управляющих знаков`); return item }
 const integer = (item: unknown, label: string, min: number, max: number, fallback?: number) => { if (item === undefined && fallback !== undefined) return fallback; if (typeof item !== 'number' || !Number.isInteger(item) || item < min || item > max) return fail(`${label}: целое число от ${min} до ${max}`); return item }
 const id = (item: unknown, label: string) => { const result = string(item, label, 80); if (!/^[A-Za-z0-9_-]+$/.test(result)) return fail(`${label}: ID должен содержать латинские буквы, цифры, дефис или подчёркивание`); return result }
 const strings = (item: unknown, label: string, count: number, length: number, optional = false) => array(item, label, count, optional).map((part, index) => string(part, `${label}, значение ${index + 1}`, length))
 const ids = (item: unknown, label: string, count: number, optional = false) => array(item, label, count, optional).map((part, index) => id(part, `${label}, значение ${index + 1}`))
 const source = object(value, 'план', ['periodStart', 'weekType', 'confirmed', 'slots', 'groups', 'teachers', 'rooms', 'demands', 'baseline', 'pins', 'eventChains', 'preferences', 'notes'])
 if (source.confirmed !== undefined && typeof source.confirmed !== 'boolean') return fail('confirmed должен быть true или false')
 const slots = array(source.slots, 'интервалы', 100).map((part, index): Slot => { const label = `интервал ${index + 1}`, item = object(part, label, ['id', 'day', 'slot', 'start', 'end']); return { id: id(item.id, label), day: integer(item.day, label, 0, 5), slot: integer(item.slot, label, 1, 20), start: string(item.start, label, 5), end: string(item.end, label, 5) } })
 const groups = array(source.groups, 'группы', 200).map((part, index): Group => { const label = `группа ${index + 1}`, item = object(part, label, ['id', 'className', 'name', 'size', 'kind', 'partition', 'maxDaily', 'unavailableSlotIds']); if (item.kind !== 'whole' && item.kind !== 'subgroup') return fail(`${label}: kind должен быть whole или subgroup`); return { id: id(item.id, label), className: string(item.className, label, 80), name: string(item.name, label, 120), size: integer(item.size, label, 1, 1000), kind: item.kind, partition: string(item.partition, label, 80, ''), maxDaily: item.maxDaily == null ? null : integer(item.maxDaily, label, 1, 20), unavailableSlotIds: ids(item.unavailableSlotIds, label, 100, true) } })
 const teachers = array(source.teachers, 'преподаватели', 300).map((part, index): Teacher => {
  const label = `преподаватель ${index + 1}`, item = object(part, label, ['id', 'name', 'subjects', 'unavailableSlotIds', 'maxDaily', 'maxWeekly', 'maxConsecutive', 'workWindows', 'maxDailySpanMinutes', 'maxDailyGapMinutes'])
  const workWindows = array(item.workWindows, `${label}, рабочие окна`, 100, true).map((part, index): WorkWindow => {
   const windowLabel = `${label}, рабочее окно ${index + 1}`, window = object(part, windowLabel, ['day', 'start', 'end'])
   return { day: integer(window.day, windowLabel, 0, 5), start: string(window.start, windowLabel, 5), end: string(window.end, windowLabel, 5) }
  })
  return { id: id(item.id, label), name: string(item.name, label, 120), subjects: strings(item.subjects, `${label}, предметы`, 100, 160), unavailableSlotIds: ids(item.unavailableSlotIds, label, 100), maxDaily: integer(item.maxDaily, label, 1, 20), maxWeekly: integer(item.maxWeekly, label, 1, 100), maxConsecutive: integer(item.maxConsecutive, label, 1, 20), workWindows, maxDailySpanMinutes: item.maxDailySpanMinutes == null ? null : integer(item.maxDailySpanMinutes, `${label}, дневной размах`, 1, 1440), maxDailyGapMinutes: item.maxDailyGapMinutes == null ? null : integer(item.maxDailyGapMinutes, `${label}, промежутки`, 0, 1440) }
 })
 const rooms = array(source.rooms, 'кабинеты', 300).map((part, index): Room => { const label = `кабинет ${index + 1}`, item = object(part, label, ['id', 'name', 'capacity', 'tags', 'unavailableSlotIds']); return { id: id(item.id, label), name: string(item.name, label, 80), capacity: integer(item.capacity, label, 1, 5000), tags: strings(item.tags, label, 100, 80), unavailableSlotIds: ids(item.unavailableSlotIds, label, 100) } })
 const demands = array(source.demands, 'нагрузка', 2000).map((part, index): Demand => { const label = `нагрузка ${index + 1}`, item = object(part, label, ['id', 'subject', 'groupIds', 'teacherIds', 'roomIds', 'weeklyCount', 'requiredTags', 'allowedSlotIds', 'maxPerDay', 'syncKey', 'sourceLessonIds', 'activeFrom', 'activeUntil', 'weekTypes']); return { id: id(item.id, label), subject: string(item.subject, label, 160), groupIds: ids(item.groupIds, label, 200), teacherIds: ids(item.teacherIds, label, 8), roomIds: ids(item.roomIds, label, 300), weeklyCount: integer(item.weeklyCount, label, 1, 40), requiredTags: strings(item.requiredTags, label, 100, 80, true), allowedSlotIds: ids(item.allowedSlotIds, label, 100, true), maxPerDay: integer(item.maxPerDay, label, 1, 20, 20), syncKey: string(item.syncKey, label, 80, ''), sourceLessonIds: ids(item.sourceLessonIds, label, 40, true), activeFrom:item.activeFrom==null?null:string(item.activeFrom,label,10), activeUntil:item.activeUntil==null?null:string(item.activeUntil,label,10), weekTypes:strings(item.weekTypes,label,8,80,true) } })
 const assignments = (value: unknown, name: string) => array(value, name, 2000, true).map((part, index): Assignment => { const label = `${name}, запись ${index + 1}`, item = object(part, label, ['eventId', 'slotId', 'roomId']); return { eventId: id(item.eventId, label), slotId: id(item.slotId, label), roomId: id(item.roomId, label) } })
 const preferences = object(source.preferences || {}, 'приоритеты', ['earlyWeight', 'changeWeight', 'roomChangeWeight'])
 const eventChains = array(source.eventChains, 'связки событий', 2000, true).map((part, index): EventChain => {
  const label = `связка ${index + 1}`, item = object(part, label, ['id', 'eventIds', 'sameDay', 'maxGapMinutes'])
  if (item.sameDay !== undefined && typeof item.sameDay !== 'boolean') return fail(`${label}: sameDay должен быть true или false`)
  return { id: id(item.id, label), eventIds: ids(item.eventIds, `${label}, события`, 40), sameDay: item.sameDay !== false, maxGapMinutes: item.maxGapMinutes == null ? null : integer(item.maxGapMinutes, `${label}, промежуток`, 0, 7200) }
 })
 return { periodStart: string(source.periodStart, 'начало недели', 10), weekType:string(source.weekType,'тип недели',80,''), confirmed: source.confirmed === true, slots, groups, teachers, rooms, demands, baseline: assignments(source.baseline, 'основа'), pins: assignments(source.pins, 'закрепления'), eventChains, preferences: { earlyWeight: integer(preferences.earlyWeight, 'вес раннего времени', 0, 100, 1), changeWeight: integer(preferences.changeWeight, 'вес сохранения времени', 0, 1000, 100), roomChangeWeight: integer(preferences.roomChangeWeight, 'вес сохранения кабинета', 0, 100, 10) }, notes: string(source.notes, 'примечание', 2000, '') }
}

function dateText(value?: string) { if (!value) return ''; const date = new Date(value); return Number.isNaN(date.getTime()) ? '' : date.toLocaleString('en-GB', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit', timeZone: 'Europe/Moscow' }) }
function validation(input: PlanningInput): string[] {
 const errors: string[] = [], integer = (value: number, min: number, max: number) => Number.isInteger(value) && value >= min && value <= max
 const date = new Date(`${input.periodStart}T12:00:00Z`)
 if (!/^\d{4}-\d{2}-\d{2}$/.test(input.periodStart) || Number.isNaN(date.getTime()) || date.getUTCDay() !== 1 || date.toISOString().slice(0, 10) !== input.periodStart) errors.push('Начало недели должно быть понедельником.')
 if (input.slots.length > 100 || input.groups.length > 200 || input.teachers.length > 300 || input.rooms.length > 300) errors.push('Превышен размер плана: до 100 интервалов, 200 групп, 300 учителей и кабинетов.')
 for (const [key, rows] of Object.entries({ slots: input.slots, groups: input.groups, teachers: input.teachers, rooms: input.rooms, demands: input.demands })) {
  const ids = new Set<string>()
  if (rows.some(row => !row || typeof row.id !== 'string' || !/^[A-Za-z0-9_-]{1,80}$/.test(row.id) || ids.has(row.id) || !ids.add(row.id))) errors.push(`Проверьте уникальные идентификаторы раздела «${key}».`)
 }
 if (input.slots.some(slot => !integer(slot.day, 0, 5) || !integer(slot.slot, 1, 20) || !/^([01]\d|2[0-3]):[0-5]\d$/.test(slot.start) || !/^([01]\d|2[0-3]):[0-5]\d$/.test(slot.end) || slot.start >= slot.end)) errors.push('Заполните день, номер и точное время каждого интервала.')
 if (input.groups.some(group => !group.className?.trim() || !group.name?.trim() || !integer(group.size, 1, 1000) || !['whole', 'subgroup'].includes(group.kind) || (group.maxDaily !== null && group.maxDaily !== undefined && !integer(group.maxDaily, 1, 20)))) errors.push('У групп нужны класс, название и численность. Дневной предел, если задан, — от 1 до 20.')
 if (input.teachers.some(teacher => !teacher.name?.trim() || !Array.isArray(teacher.subjects) || !teacher.subjects.length || !integer(teacher.maxDaily, 1, 20) || !integer(teacher.maxWeekly, 1, 100) || !integer(teacher.maxConsecutive, 1, 20))) errors.push('Укажите квалификацию и все три лимита каждого преподавателя.')
 const validTime = (value: string) => /^([01]\d|2[0-3]):[0-5]\d$/.test(value)
 if (input.teachers.some(teacher => (teacher.workWindows || []).length > 100 || (teacher.workWindows || []).some(window => !integer(window.day, 0, 5) || !validTime(window.start) || !validTime(window.end) || window.start >= window.end) || (teacher.maxDailySpanMinutes != null && !integer(teacher.maxDailySpanMinutes, 1, 1440)) || (teacher.maxDailyGapMinutes != null && !integer(teacher.maxDailyGapMinutes, 0, 1440)))) errors.push('Проверьте явные рабочие окна и минутные пределы размаха/промежутков преподавателей.')
 if (input.rooms.some(room => !room.name?.trim() || !integer(room.capacity, 1, 5000) || !Array.isArray(room.tags))) errors.push('Укажите название и подтверждённую вместимость каждого кабинета.')
 if (input.demands.some(demand => !demand.subject?.trim() || !Array.isArray(demand.groupIds) || !demand.groupIds.length || !Array.isArray(demand.teacherIds) || !demand.teacherIds.length || demand.teacherIds.length > 8 || !Array.isArray(demand.roomIds) || !demand.roomIds.length || !integer(demand.weeklyCount, 1, 40) || !integer(demand.maxPerDay, 1, 20))) errors.push('У нагрузки нужны предмет, группы, преподаватели, кабинеты и число занятий с дневным пределом.')
 const expanded = input.demands.reduce((sum, demand) => sum + (Number.isFinite(demand.weeklyCount) ? demand.weeklyCount : 0), 0)
 const eventIds = new Set(input.demands.flatMap(demand => Array.from({ length: integer(demand.weeklyCount, 1, 40) ? demand.weeklyCount : 0 }, (_, occurrence) => `${demand.id}_${occurrence}`)))
 const chainIds = new Set<string>(), chains = input.eventChains || []
 if (chains.length > 2000 || chains.reduce((sum, chain) => sum + chain.eventIds.length, 0) > 4000 || chains.some(chain => !/^[A-Za-z0-9_-]{1,80}$/.test(chain.id) || chainIds.has(chain.id) || !chainIds.add(chain.id) || chain.eventIds.length < 2 || chain.eventIds.length > 40 || new Set(chain.eventIds).size !== chain.eventIds.length || chain.eventIds.some(id => !eventIds.has(id)) || typeof chain.sameDay !== 'boolean' || (chain.maxGapMinutes !== null && !integer(chain.maxGapMinutes, 0, 7200)))) errors.push('Проверьте связки: уникальные ID, 2–40 известных событий в заданном порядке и явный допустимый промежуток.')
 if(input.demands.some(d=>(d.activeFrom!=null&&!/^\d{4}-\d{2}-\d{2}$/.test(d.activeFrom))||(d.activeUntil!=null&&!/^\d{4}-\d{2}-\d{2}$/.test(d.activeUntil))||(d.activeFrom&&d.activeUntil&&d.activeFrom>d.activeUntil))) errors.push('Проверьте даты действия нагрузки.');
 if (expanded > 2000) errors.push('План содержит больше 2000 занятий за неделю.')
 if (new TextEncoder().encode(JSON.stringify(input)).length > 512 * 1024) errors.push('Условия должны занимать не больше 512 КБ. Разделите слишком большой план.')
 if (input.notes.length > 2000) errors.push('Примечание должно быть не длиннее 2000 символов.')
 return errors
}
class ApiError extends Error { status: number; issues:Diagnostic[]; constructor(message: string, status: number, issues:Diagnostic[]=[]) { super(message); this.status = status;this.issues=issues } }
async function api<T>(url: string, options?: RequestInit): Promise<T> {
 const controller = new AbortController(), timeout = setTimeout(() => controller.abort(), 20000), abort = () => controller.abort()
 options?.signal?.addEventListener('abort', abort, { once: true })
 try {
  const response = await apiFetch(url, { ...options, signal: controller.signal })
  let data: unknown; try { data = await response.json() } catch { data = null }
  if (!response.ok) { const detail = data && typeof data === 'object' && 'detail' in data ? (data as { detail: unknown }).detail : null; const problem = detail && typeof detail === 'object' ? detail as { message?: unknown; issues?: Diagnostic[] } : null; const message = typeof problem?.message === 'string' ? problem.message + ' ' + (Array.isArray(problem.issues) ? problem.issues.slice(0, 5).map(item => item.message).join(' ') : '') : null; throw new ApiError(typeof detail === 'string' ? detail : message || (response.status === 409 ? 'Версия изменилась. Введённые условия сохранены локально.' : response.status === 403 ? 'Планировщик доступен директору и завучу.' : 'Не удалось выполнить действие. Повторите запрос.'), response.status,Array.isArray(problem?.issues)?problem.issues:[]) }
  return data as T
 } catch (error) { if (error instanceof ApiError) throw error; throw new ApiError(controller.signal.aborted ? 'Сервер не ответил вовремя. Локальные условия сохранены.' : 'Нет связи с сервером. Локальные условия сохранены, действие можно повторить.', 0) }
 finally { clearTimeout(timeout); options?.signal?.removeEventListener('abort', abort) }
}
const post = (body: unknown): RequestInit => ({ method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) })
function Badge({ children, tone = '' }: { children: ReactNode; tone?: string }) { return <span className={`sp-badge ${tone}`}>{children}</span> }
function Field({ label, children, hint }: { label: string; children: ReactNode; hint?: string }) { return <label className="sp-field"><span>{label}</span>{children}{hint && <small>{hint}</small>}</label> }
function Multiple({ label, values, options, onChange, disabled, hint }: { label: string; values: string[]; options: { id: string; name: string }[]; onChange: (values: string[]) => void; disabled?: boolean; hint?: string }) { return <Field label={label} hint={hint}><select multiple aria-label={label} size={Math.min(4, Math.max(2, options.length))} value={values} disabled={disabled} onChange={event => onChange([...event.target.selectedOptions].map(option => option.value))}>{options.map(option => <option key={option.id} value={option.id}>{option.name}</option>)}</select>{!options.length && <small>Сначала добавьте соответствующие данные.</small>}</Field> }
function tabNavigation(event: React.KeyboardEvent<HTMLDivElement>) {
 if (!['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key) || (event.target as HTMLElement).getAttribute('role') !== 'tab') return
 const buttons = [...event.currentTarget.querySelectorAll<HTMLButtonElement>('[role="tab"]')], current = buttons.indexOf(event.target as HTMLButtonElement)
 if (current < 0) return
 event.preventDefault(); const index = event.key === 'Home' ? 0 : event.key === 'End' ? buttons.length - 1 : (current + (event.key === 'ArrowRight' ? 1 : -1) + buttons.length) % buttons.length
 if (!buttons[index]?.disabled) { buttons[index].focus(); buttons[index].click() }
}

