 async function makeQuestions() { await command('questions', async () => { const next = await api<unknown>('/api/planning/questions', post({ expectedConfigRevision: config?.revision || 0 })); if (alive.current) { setQuestions(listOf<Question>(next, 'questions')); setTab('questions'); setNotice('Вопросы подготовлены только локально. MAX не подключён, отправки не было.') } }) }
